// طابور العمل دون اتصال: دوال نقية على حالة غير قابلة للتعديل، فتُختبر هنا ويستعملها الموبايل كما هي.
// الحفظ على الجهاز (التخزين) خارج هذا الملف عمداً.
// The offline work queue: pure functions over immutable state, tested here and used by mobile as is.
// Persistence on the device (storage) is deliberately outside this file.

export const QUEUE_MAX_ATTEMPTS = 8;
export const QUEUE_BACKOFF_CAP_MS = 5 * 60_000;

export interface QueuedOp {
  // معرّف يولّده الجهاز؛ يصبح `Idempotency-Key` فلا تتكرر العملية إن أُعيد إرسالها.
  // Generated by the device; it becomes the `Idempotency-Key` so a resend never duplicates the operation.
  id: string;
  kind: string;
  payload: unknown;
  createdAt: number;
  attempts: number;
  nextAttemptAt: number;
  status: 'pending' | 'failed';
  lastError?: string;
}

export type OfflineQueue = readonly QueuedOp[];

export const backoffMs = (attempts: number): number =>
  Math.min(2 ** Math.max(0, attempts) * 1000, QUEUE_BACKOFF_CAP_MS);

// أخطاء الشبكة والخادم المؤقتة تُعاد؛ أخطاء العميل (400/403/404/409/422) لا تنفع بتكرارها.
// Network and transient server errors retry; client errors (400/403/404/409/422) never succeed by repeating.
export const isRetryableStatus = (status: number | null): boolean =>
  status === null || status === 408 || status === 429 || status >= 500;

export const enqueue = (
  queue: OfflineQueue,
  op: { id: string; kind: string; payload: unknown },
  now: number,
): OfflineQueue =>
  // نفس المعرّف لا يُضاف مرتين (ضغطة مزدوجة أو إعادة تحميل). The same id is never added twice.
  queue.some((q) => q.id === op.id)
    ? queue
    : [
        ...queue,
        { ...op, createdAt: now, attempts: 0, nextAttemptAt: now, status: 'pending' as const },
      ];

// الأقدم أولاً: الترتيب يحفظ تسلسل المسح كما حدث. Oldest first: keeps the scan order as it happened.
export const nextDue = (queue: OfflineQueue, now: number): QueuedOp | undefined =>
  queue
    .filter((q) => q.status === 'pending' && q.nextAttemptAt <= now)
    .sort((a, b) => a.createdAt - b.createdAt)[0];

export const markSent = (queue: OfflineQueue, id: string): OfflineQueue =>
  queue.filter((q) => q.id !== id);

export const markFailed = (
  queue: OfflineQueue,
  id: string,
  failure: { status: number | null; message: string },
  now: number,
): OfflineQueue =>
  queue.map((q) => {
    if (q.id !== id) return q;
    const attempts = q.attempts + 1;
    const giveUp = !isRetryableStatus(failure.status) || attempts >= QUEUE_MAX_ATTEMPTS;
    return {
      ...q,
      attempts,
      lastError: failure.message,
      status: giveUp ? ('failed' as const) : ('pending' as const),
      nextAttemptAt: now + backoffMs(attempts),
    };
  });

// يعيد محاولة العمليات الفاشلة يدوياً (زر «أعد المحاولة»). Manually retry failed operations.
export const retryFailed = (queue: OfflineQueue, now: number): OfflineQueue =>
  queue.map((q) =>
    q.status === 'failed'
      ? { ...q, status: 'pending' as const, attempts: 0, nextAttemptAt: now }
      : q,
  );

export const queueStats = (queue: OfflineQueue): { pending: number; failed: number } => ({
  pending: queue.filter((q) => q.status === 'pending').length,
  failed: queue.filter((q) => q.status === 'failed').length,
});

// الكاميرا تقرأ الباركود نفسه عشرات المرات في الثانية؛ نقبله مرة واحدة خلال النافذة.
// The camera reads the same barcode dozens of times a second; accept it once per window.
export const createScanGate = (windowMs: number): ((barcode: string, now: number) => boolean) => {
  let last: { barcode: string; at: number } | null = null;
  return (barcode, now) => {
    if (last && last.barcode === barcode && now - last.at < windowMs) return false;
    last = { barcode, at: now };
    return true;
  };
};
